<?php
require_once __DIR__ . '/_bootstrap.php'; b2cRequireCustomer(); $uid=(int)currentUserId();$error='';$placed=0;
$items=b2cRows("SELECT ci.product_id,ci.quantity,p.name,p.retail_price,(ci.quantity*p.retail_price) subtotal FROM cart_items ci JOIN carts c ON c.id=ci.cart_id JOIN products p ON p.id=ci.product_id AND p.status='active' WHERE c.user_id=? AND c.status='active'",[$uid]);$total=array_sum(array_map(static fn($i)=>(float)$i['subtotal'],$items));
if($_SERVER['REQUEST_METHOD']==='POST'&&$items){verifyCsrfToken();$address=trim((string)($_POST['shipping_address']??''));$payment=(string)($_POST['payment_method']??'cash_on_delivery');$allowed=['cash_on_delivery','mtn_mobile_money','orange_money'];if($address==='')$error='Please enter a delivery address.';elseif(!in_array($payment,$allowed,true))$error='Please select a valid payment method.';elseif(!$b2cDb)$error='Checkout is temporarily unavailable.';else{try{$b2cDb->beginTransaction();$number='QS-'.date('YmdHis').'-'.random_int(100,999);$s=$b2cDb->prepare('INSERT INTO orders (user_id,order_number,subtotal,total_amount,payment_method,order_status) VALUES (?,?,?,?,?,"Pending")');$s->execute([$uid,$number,$total,$total,$payment]);$placed=(int)$b2cDb->lastInsertId();$line=$b2cDb->prepare('INSERT INTO order_items (order_id,product_id,quantity,unit_price,subtotal) VALUES (?,?,?,?,?)');foreach($items as $i)$line->execute([$placed,$i['product_id'],$i['quantity'],$i['retail_price'],$i['subtotal']]);$b2cDb->prepare('DELETE ci FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE c.user_id=? AND c.status="active"')->execute([$uid]);$b2cDb->prepare('UPDATE carts SET status="converted" WHERE user_id=? AND status="active"')->execute([$uid]);$b2cDb->commit();}catch(Throwable $e){if($b2cDb->inTransaction())$b2cDb->rollBack();$error='We could not place your order. Please try again.';}}}
b2cPage('Checkout'); ?>
<div class="section-head"><div><h1>Secure checkout</h1><p>Almost there. Confirm your delivery details.</p></div></div>
<?php if($placed): ?><div class="alert"><h3>Order placed successfully</h3><p>Thank you for shopping with Quincy Store.</p><a class="btn" href="<?= e(BASE_URL) ?>/customer/order-details.php?id=<?= $placed ?>">View your order</a></div><?php elseif($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?>
<?php if(!$placed && !$items): ?><div class="empty"><h2>Your cart is empty</h2><a class="btn" href="products.php">Browse products</a></div><?php elseif(!$placed): ?><div class="layout"><form class="panel form" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><label>Delivery address<textarea name="shipping_address" required placeholder="Street, city, region"></textarea></label><label>Payment method<select name="payment_method"><option value="cash_on_delivery">Cash on delivery</option><option value="mtn_mobile_money">MTN Mobile Money</option><option value="orange_money">Orange Money</option></select></label><button class="btn gold" type="submit">Place order · <?= e(formatPrice($total)) ?></button><p class="muted">Your information is encrypted and never shared.</p></form><aside class="panel"><h2>Order summary</h2><?php foreach($items as $i): ?><div class="summary-line"><span><?= e($i['name']) ?> × <?= (int)$i['quantity'] ?></span><strong><?= e(formatPrice($i['subtotal'])) ?></strong></div><?php endforeach; ?><div class="summary-line total"><strong>Total</strong><strong><?= e(formatPrice($total)) ?></strong></div></aside></div><?php endif; ?><?php b2cEnd(); ?>